#!/bin/sh
# aster-agent installer — modeled on komari-agent's install script.
# Supports Linux (systemd / OpenRC) and macOS (launchd).
# Usage: curl -fsSL <raw-url>/agent/install.sh | sudo sh -s -- --token <TOKEN> [--listen :9977]
#   --token <t>       required, bearer token generated by Aster.app
#   --listen <addr>   listen address, default :9977
#   --state-dir <d>   TLS state directory, default /var/lib/aster-agent
#   --ghproxy <p>     GitHub proxy prefix, e.g. https://ghproxy.example (for CN networks)
#   --version <v>     release tag to install, default latest
#   --repo <o/r>      GitHub repository, default set below at release time
#   --sha256 <hex>    optional: verify the downloaded binary against this digest
#   --domain <d>      Linux only: hide the agent behind a real domain on 443.
#                     PREREQUISITE: the domain's A record must already point at
#                     this server (or be proxied through Cloudflare). The agent
#                     then listens on loopback only and Caddy/nginx terminates
#                     TLS with a CA certificate — in Aster.app just enter
#                     https://<domain>, no fingerprint needed.
#   --proxy <p>       caddy | nginx | auto (default auto: existing caddy >
#                     existing nginx > install caddy)
#   --uninstall       stop the service, remove the binary and any proxy block
set -eu

REPO="maow318/astervps"
TOKEN=""
LISTEN=":9977"
STATE_DIR="/var/lib/aster-agent"
GHPROXY=""
VERSION="latest"
SHA256=""
DOMAIN=""
PROXY="auto"
UNINSTALL=0
NGINX_CONF=/etc/nginx/conf.d/aster-agent.conf
CADDYFILE=/etc/caddy/Caddyfile
BIN=/usr/local/bin/aster-agent
SERVICE=aster-agent
TOKEN_DIR=/etc/aster-agent
TOKEN_FILE=$TOKEN_DIR/token
PLIST=/Library/LaunchDaemons/cc.aster.agent.plist
DARWIN_LOG=/var/log/aster-agent.log

log() { printf '%s\n' "$1"; }
fail() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }

while [ "$#" -gt 0 ]; do
  case "$1" in
    --token) TOKEN="$2"; shift 2 ;;
    --listen) LISTEN="$2"; shift 2 ;;
    --state-dir) STATE_DIR="$2"; shift 2 ;;
    --ghproxy) GHPROXY="$2"; shift 2 ;;
    --version) VERSION="$2"; shift 2 ;;
    --repo) REPO="$2"; shift 2 ;;
    --sha256) SHA256="$2"; shift 2 ;;
    --domain) DOMAIN="$2"; shift 2 ;;
    --proxy) PROXY="$2"; shift 2 ;;
    --uninstall) UNINSTALL=1; shift ;;
    *) log "ignoring unknown argument: $1"; shift ;;
  esac
done

# TLS SNI and Caddy site blocks are case-sensitive; DNS is not. Normalize so a
# user typing RN.Example.com cannot produce a site block nobody matches.
DOMAIN=$(printf '%s' "$DOMAIN" | tr '[:upper:]' '[:lower:]')

[ "$(id -u)" = 0 ] || fail "run as root (sudo)"

stop_previous() {
  if [ "$(uname -s)" = "Darwin" ]; then
    if [ -f "$PLIST" ]; then
      launchctl bootout system "$PLIST" 2>/dev/null || true
      rm -f "$PLIST"
    fi
    return 0
  fi
  if command -v systemctl >/dev/null 2>&1 && [ -f "/etc/systemd/system/$SERVICE.service" ]; then
    systemctl stop "$SERVICE" 2>/dev/null || true
    systemctl disable "$SERVICE" 2>/dev/null || true
    rm -f "/etc/systemd/system/$SERVICE.service"
    systemctl daemon-reload
  elif command -v rc-service >/dev/null 2>&1 && [ -f "/etc/init.d/$SERVICE" ]; then
    rc-service "$SERVICE" stop 2>/dev/null || true
    rc-update del "$SERVICE" default 2>/dev/null || true
    rm -f "/etc/init.d/$SERVICE"
  fi
}

remove_proxy_config() {
  if [ -f "$CADDYFILE" ] && grep -q '# aster-agent begin' "$CADDYFILE" 2>/dev/null; then
    sed -i '/# aster-agent begin/,/# aster-agent end/d' "$CADDYFILE"
    systemctl reload caddy 2>/dev/null || true
  fi
  # Dockerized Caddy: find the container's bind-mounted Caddyfile and clean it.
  if command -v docker >/dev/null 2>&1; then
    container=$(docker ps --format '{{.Names}} {{.Image}}' 2>/dev/null \
      | awk 'tolower($0) ~ /caddy/ {print $1; exit}') || true
    if [ -n "${container:-}" ]; then
      mounted=$(docker inspect "$container" \
        --format '{{range .Mounts}}{{.Destination}} {{.Source}}{{println}}{{end}}' 2>/dev/null \
        | awk '$1 == "/etc/caddy/Caddyfile" {print $2; exit}')
      if [ -n "${mounted:-}" ] && grep -q '# aster-agent begin' "$mounted" 2>/dev/null; then
        sed -i '/# aster-agent begin/,/# aster-agent end/d' "$mounted"
        docker exec "$container" caddy reload --config /etc/caddy/Caddyfile >/dev/null 2>&1 || true
        log "removed the aster-agent block from $mounted"
      fi
    fi
  fi
  if [ -f "$NGINX_CONF" ]; then
    rm -f "$NGINX_CONF"
    systemctl reload nginx 2>/dev/null || true
  fi
  rm -f /etc/cron.d/aster-certbot-renew
}

if [ "$UNINSTALL" = 1 ]; then
  stop_previous
  [ "$(uname -s)" = "Linux" ] && remove_proxy_config
  rm -f "$BIN" "$TOKEN_FILE"
  rmdir "$TOKEN_DIR" 2>/dev/null || true
  log "aster-agent uninstalled (state dir $STATE_DIR kept; remove manually if desired)"
  exit 0
fi

[ -n "$TOKEN" ] || fail "--token is required"
[ "$REPO" != "ASTER_REPO_PLACEHOLDER" ] || fail "release repository not configured yet; pass --repo <owner>/<repo> or install manually (see agent/README.md)"
command -v curl >/dev/null 2>&1 || fail "curl is required; install it with your package manager"

case "$(uname -s)" in
  Linux) PLATFORM=linux ;;
  Darwin) PLATFORM=darwin ;;
  *) fail "unsupported system: $(uname -s)" ;;
esac

case "$(uname -m)" in
  x86_64) ARCH=amd64 ;;
  aarch64 | arm64) ARCH=arm64 ;;
  armv7* | armv6*) ARCH=arm ;;
  i386 | i686) ARCH=386 ;;
  *) fail "unsupported architecture: $(uname -m)" ;;
esac

# ---- domain mode pre-flight -------------------------------------------------
if [ -n "$DOMAIN" ]; then
  [ "$PLATFORM" = "linux" ] || fail "--domain mode is Linux-only (the local Mac never needs it)"
  case "$PROXY" in caddy|nginx|auto) ;; *) fail "--proxy must be caddy, nginx or auto" ;; esac
  AGENT_PORT="${LISTEN##*:}"

  # Self-heal an interrupted apt run before anything else.
  dpkg --configure -a >/dev/null 2>&1 || true

  # Detect what already terminates TLS on this box — including Caddy running
  # inside Docker — before deciding how to wire the proxy.
  DOCKER_CADDY=""
  DOCKER_NGINX=""
  if command -v docker >/dev/null 2>&1; then
    DOCKER_CADDY=$(docker ps --format '{{.Names}} {{.Image}}' 2>/dev/null \
      | awk 'tolower($0) ~ /caddy/ {print $1; exit}') || true
    DOCKER_NGINX=$(docker ps --format '{{.Names}} {{.Image}}' 2>/dev/null \
      | awk 'tolower($0) ~ /nginx|npm|proxy-manager/ {print $1; exit}') || true
  fi
  PROXY_KIND=""
  case "$PROXY" in
    caddy)
      if command -v caddy >/dev/null 2>&1; then PROXY_KIND=caddy-host
      elif [ -n "$DOCKER_CADDY" ]; then PROXY_KIND=caddy-docker
      else PROXY_KIND=install-caddy; fi ;;
    nginx)
      if command -v nginx >/dev/null 2>&1; then PROXY_KIND=nginx-host
      elif [ -n "$DOCKER_NGINX" ]; then PROXY_KIND=nginx-docker
      else fail "--proxy nginx requested but nginx is not installed"; fi ;;
    auto)
      if command -v caddy >/dev/null 2>&1; then PROXY_KIND=caddy-host
      elif [ -n "$DOCKER_CADDY" ]; then PROXY_KIND=caddy-docker
      elif command -v nginx >/dev/null 2>&1; then PROXY_KIND=nginx-host
      elif [ -n "$DOCKER_NGINX" ]; then PROXY_KIND=nginx-docker
      else PROXY_KIND=install-caddy; fi ;;
  esac

  if [ "$PROXY_KIND" = "nginx-docker" ]; then
    GATEWAY=$(docker inspect "$DOCKER_NGINX" \
      --format '{{range .NetworkSettings.Networks}}{{.Gateway}}{{println}}{{end}}' \
      | awk 'NF {print; exit}')
    [ -n "$GATEWAY" ] || fail "cannot determine the docker network gateway of container $DOCKER_NGINX"
    LISTEN="$GATEWAY:$AGENT_PORT"
    log "detected dockerized nginx ($DOCKER_NGINX); agent will listen on $LISTEN"
  elif [ "$PROXY_KIND" = "caddy-docker" ]; then
    # A leftover half-installed host caddy would fight the container for 443.
    systemctl disable --now caddy >/dev/null 2>&1 || true
    GATEWAY=$(docker inspect "$DOCKER_CADDY" \
      --format '{{range .NetworkSettings.Networks}}{{.Gateway}}{{println}}{{end}}' \
      | awk 'NF {print; exit}')
    [ -n "$GATEWAY" ] || fail "cannot determine the docker network gateway of container $DOCKER_CADDY"
    # The agent binds the bridge gateway: reachable from the container, not
    # from the public interface.
    LISTEN="$GATEWAY:$AGENT_PORT"
    log "detected dockerized Caddy ($DOCKER_CADDY); agent will listen on $LISTEN"
  else
    LISTEN="127.0.0.1:$AGENT_PORT"
  fi

  if [ "$PROXY_KIND" = "install-caddy" ]; then
    if command -v ss >/dev/null 2>&1 && ss -ltn 2>/dev/null | grep -q ':443 '; then
      fail "port 443 is already in use by something this script does not recognize; configure your existing proxy manually (see docs/aster-protocol.md) or free the port"
    fi
  fi

  log "domain mode: $DOMAIN (proxy: $PROXY_KIND)"
  log "prerequisite: the domain's A record must already point at this server,"
  log "or be proxied through a CDN such as Cloudflare."
  RESOLVED=$(getent ahosts "$DOMAIN" 2>/dev/null | awk '{print $1; exit}' || true)
  if [ -z "$RESOLVED" ]; then
    PUBLIC_IP=$(curl -4fsS --max-time 8 https://api.ipify.org 2>/dev/null || true)
    fail "cannot resolve $DOMAIN — add an A record first: $DOMAIN -> ${PUBLIC_IP:-your-server-IP}"
  fi
  PUBLIC_IP=$(curl -4fsS --max-time 8 https://api.ipify.org 2>/dev/null || true)
  if [ -n "$PUBLIC_IP" ] && [ "$RESOLVED" != "$PUBLIC_IP" ]; then
    log "NOTE: $DOMAIN resolves to $RESOLVED but this server's IP is $PUBLIC_IP."
    log "      Expected if the domain is behind a CDN proxy (Cloudflare); otherwise fix the A record."
  fi
fi

ASSET="aster-agent-$PLATFORM-$ARCH"
if [ "$VERSION" = "latest" ]; then
  URL="https://github.com/$REPO/releases/latest/download/$ASSET"
else
  URL="https://github.com/$REPO/releases/download/$VERSION/$ASSET"
fi
# Until a GitHub release with assets exists, binaries are served from the
# repository's `dist` branch; the release URL is preferred once it works.
FALLBACK_URL="https://raw.githubusercontent.com/$REPO/dist/$ASSET"
if [ -n "$GHPROXY" ]; then
  URL="$GHPROXY/$URL"
  FALLBACK_URL="$GHPROXY/$FALLBACK_URL"
fi

stop_previous

log "downloading $URL"
if ! curl -fL -o "$BIN.tmp" "$URL"; then
  log "release download unavailable, falling back to $FALLBACK_URL"
  curl -fL -o "$BIN.tmp" "$FALLBACK_URL" || fail "download failed"
fi
if [ -n "$SHA256" ]; then
  if command -v sha256sum >/dev/null 2>&1; then
    ACTUAL=$(sha256sum "$BIN.tmp" | cut -d' ' -f1)
  else
    ACTUAL=$(shasum -a 256 "$BIN.tmp" | cut -d' ' -f1)
  fi
  [ "$ACTUAL" = "$SHA256" ] || { rm -f "$BIN.tmp"; fail "sha256 mismatch: got $ACTUAL"; }
  log "sha256 verified"
fi
mkdir -p "$(dirname "$BIN")"
chmod 755 "$BIN.tmp"
mv "$BIN.tmp" "$BIN"

mkdir -p "$STATE_DIR"

# The token lives in a root-only file instead of the unit's command line, so
# it never shows up in `ps` output or the world-readable unit file.
mkdir -p "$TOKEN_DIR"
umask_previous=$(umask)
umask 077
printf '%s' "$TOKEN" > "$TOKEN_FILE"
umask "$umask_previous"
chmod 600 "$TOKEN_FILE"

if [ "$PLATFORM" = "darwin" ]; then
  cat > "$PLIST" << EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>cc.aster.agent</string>
  <key>ProgramArguments</key>
  <array>
    <string>$BIN</string>
    <string>--listen</string><string>$LISTEN</string>
    <string>--token-file</string><string>$TOKEN_FILE</string>
    <string>--state-dir</string><string>$STATE_DIR</string>
  </array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>StandardOutPath</key><string>$DARWIN_LOG</string>
  <key>StandardErrorPath</key><string>$DARWIN_LOG</string>
</dict>
</plist>
EOF
  launchctl bootstrap system "$PLIST"
  sleep 2
  FINGERPRINT=$(grep -o 'fingerprint: [0-9a-f]*' "$DARWIN_LOG" 2>/dev/null | tail -1 | cut -d' ' -f2 || true)
elif command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]; then
  cat > "/etc/systemd/system/$SERVICE.service" << EOF
[Unit]
Description=Aster Agent
After=network-online.target

[Service]
ExecStart=$BIN --listen $LISTEN --token-file $TOKEN_FILE --state-dir $STATE_DIR
Restart=always
RestartSec=3
# Hardening: the agent only reads system state; it never needs new privileges,
# a writable /usr//etc, or anyone's home directory.
NoNewPrivileges=yes
ProtectSystem=full
ProtectHome=read-only
PrivateTmp=yes
ProtectKernelTunables=yes
ProtectControlGroups=yes
RestrictSUIDSGID=yes

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable --now "$SERVICE"
  sleep 2
  FINGERPRINT=$(journalctl -u "$SERVICE" --no-pager 2>/dev/null | grep -o 'fingerprint: [0-9a-f]*' | tail -1 | cut -d' ' -f2 || true)
elif command -v rc-service >/dev/null 2>&1; then
  cat > "/etc/init.d/$SERVICE" << EOF
#!/sbin/openrc-run
name="Aster Agent"
command="$BIN"
command_args="--listen $LISTEN --token-file $TOKEN_FILE --state-dir $STATE_DIR"
command_background=true
pidfile="/run/$SERVICE.pid"
output_log="/var/log/$SERVICE.log"
error_log="/var/log/$SERVICE.log"
depend() { need net; }
EOF
  chmod +x "/etc/init.d/$SERVICE"
  rc-update add "$SERVICE" default
  rc-service "$SERVICE" start
  sleep 2
  FINGERPRINT=$(grep -o 'fingerprint: [0-9a-f]*' "/var/log/$SERVICE.log" 2>/dev/null | tail -1 | cut -d' ' -f2 || true)
else
  fail "no supported init system found (systemd or OpenRC)"
fi

# ---- domain mode: reverse proxy + real certificate --------------------------

# Existing Caddyfiles often end with a whitelist guard such as
#   @not_known not host a.example b.example
#   respond @not_known "Forbidden" 403
# which answers 403 for every other name — including Let's Encrypt's HTTP
# challenge, so the new domain could never get a certificate. Add ourselves to
# every such whitelist we find.
allow_in_host_whitelists() {
  target="$1"
  grep -q "not host" "$target" 2>/dev/null || return 0
  grep "not host" "$target" | grep -q "$DOMAIN" && return 0
  sed -i "/not host/ s/\$/ $DOMAIN/" "$target"
  log "added $DOMAIN to the host whitelist in $(basename "$target")"
}

write_caddy_block() {
  target="$1"
  upstream="$2"
  sed -i '/# aster-agent begin/,/# aster-agent end/d' "$target"
  allow_in_host_whitelists "$target"
  cat >> "$target" << EOF
# aster-agent begin
$DOMAIN {
  reverse_proxy https://$upstream {
    transport http {
      tls_insecure_skip_verify
    }
  }
}
# aster-agent end
EOF
}

# verify_domain polls the public endpoint until the certificate is live. A 401
# is the success signal: the agent answered through the proxy without a token.
verify_domain() {
  log "verifying https://$DOMAIN (issuing the certificate can take ~30 s)"
  attempt=0
  while [ "$attempt" -lt 12 ]; do
    attempt=$((attempt + 1))
    CODE=$(curl -s -o /dev/null -w '%{http_code}' --max-time 8 "https://$DOMAIN/v1/meta" 2>/dev/null || true)
    case "$CODE" in
      401|200) log "verified: the domain serves the agent over a trusted certificate"; return 0 ;;
      403) log "  attempt $attempt: 403 (a whitelist rule is still blocking; retrying)" ;;
      000|"") log "  attempt $attempt: no answer yet (certificate pending)" ;;
      *) log "  attempt $attempt: HTTP $CODE" ;;
    esac
    sleep 5
  done
  log ""
  log "WARNING: $DOMAIN did not answer as expected yet (last code: ${CODE:-none})."
  log "Diagnose with:"
  if [ "$PROXY_KIND" = "caddy-docker" ]; then
    log "  docker logs --tail 50 $DOCKER_CADDY | grep -i $DOMAIN"
  elif [ "$PROXY_KIND" = "nginx-host" ]; then
    log "  journalctl -u nginx --no-pager | tail -30; certbot certificates"
  else
    log "  journalctl -u caddy --no-pager | tail -30"
  fi
  log "Common causes: DNS not propagated yet, port 80 blocked (needed for the"
  log "certificate challenge), or a CDN proxy terminating TLS in front."
  return 1
}

setup_caddy() {
  if ! command -v caddy >/dev/null 2>&1; then
    log "installing Caddy (official repository)"
    command -v apt-get >/dev/null 2>&1 || fail "automatic Caddy install needs apt; install caddy or nginx manually, then re-run"
    log "step 1/3: refreshing apt (a few minutes on slow machines)"
    apt-get update -q
    apt-get install -y -q debian-keyring debian-archive-keyring apt-transport-https gnupg
    log "step 2/3: adding the Caddy repository"
    curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' \
      | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
    curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' \
      > /etc/apt/sources.list.d/caddy-stable.list
    log "step 3/3: installing caddy"
    apt-get update -q && apt-get install -y -q caddy
  fi
  touch "$CADDYFILE"
  write_caddy_block "$CADDYFILE" "127.0.0.1:$AGENT_PORT"
  systemctl enable --now caddy >/dev/null 2>&1 || true
  if ! systemctl reload caddy 2>&1; then
    log "reload failed, restarting caddy"
    systemctl restart caddy || fail "caddy failed to start; check: journalctl -u caddy | tail -30"
  fi
  log "Caddy configured; the certificate is issued and renewed automatically."
}

setup_nginx() {
  cat > "$NGINX_CONF" << EOF
server {
    listen 80;
    server_name $DOMAIN;
    location / {
        proxy_pass https://127.0.0.1:$AGENT_PORT;
        proxy_ssl_verify off;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
    }
}
EOF
  nginx -t || fail "nginx config test failed"
  systemctl reload nginx 2>/dev/null || systemctl restart nginx
  if ! command -v certbot >/dev/null 2>&1; then
    log "installing certbot (a few minutes on slow machines)"
    if command -v apt-get >/dev/null 2>&1; then
      apt-get update -q && apt-get install -y -q certbot python3-certbot-nginx
    elif command -v dnf >/dev/null 2>&1; then
      dnf install -y -q certbot python3-certbot-nginx
    elif command -v yum >/dev/null 2>&1; then
      yum install -y -q certbot python3-certbot-nginx
    else
      fail "certbot unavailable; install it manually, then run: certbot --nginx -d $DOMAIN"
    fi
  fi
  log "requesting the certificate from Let's Encrypt"
  certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos --register-unsafely-without-email \
    --redirect --keep-until-expiring \
    || fail "certificate issuance failed (is port 80 reachable from the internet and DNS live?); fix, then re-run this installer"
  # Renewal: certbot ships a systemd timer on most distros; fall back to cron.
  if systemctl list-timers 2>/dev/null | grep -q certbot; then
    log "renewal handled by the certbot systemd timer"
  elif [ -d /etc/cron.d ]; then
    printf '0 3 * * * root certbot renew --quiet --deploy-hook "systemctl reload nginx"\n' \
      > /etc/cron.d/aster-certbot-renew
    log "renewal cron installed at /etc/cron.d/aster-certbot-renew"
  fi
  log "nginx + Let's Encrypt configured."
}

setup_caddy_docker() {
  CADDYFILE_HOST=$(docker inspect "$DOCKER_CADDY" \
    --format '{{range .Mounts}}{{.Destination}} {{.Source}}{{println}}{{end}}' \
    | awk '$1 == "/etc/caddy/Caddyfile" {print $2; exit}')
  if [ -z "$CADDYFILE_HOST" ]; then
    DIR_MOUNT=$(docker inspect "$DOCKER_CADDY" \
      --format '{{range .Mounts}}{{.Destination}} {{.Source}}{{println}}{{end}}' \
      | awk '$1 == "/etc/caddy" {print $2; exit}')
    [ -n "$DIR_MOUNT" ] && [ -f "$DIR_MOUNT/Caddyfile" ] && CADDYFILE_HOST="$DIR_MOUNT/Caddyfile"
  fi
  [ -n "$CADDYFILE_HOST" ] || fail "found Caddy container $DOCKER_CADDY but not its Caddyfile bind mount; add this block manually and reload:
$DOMAIN {
  reverse_proxy https://$GATEWAY:$AGENT_PORT {
    transport http {
      tls_insecure_skip_verify
    }
  }
}"
  log "updating $CADDYFILE_HOST"
  write_caddy_block "$CADDYFILE_HOST" "$GATEWAY:$AGENT_PORT"
  if ! docker exec "$DOCKER_CADDY" caddy reload --config /etc/caddy/Caddyfile 2>&1; then
    log "reload failed, restarting the container"
    docker restart "$DOCKER_CADDY" >/dev/null \
      || fail "could not restart $DOCKER_CADDY; check: docker logs --tail 50 $DOCKER_CADDY"
  fi
  log "dockerized Caddy reloaded; certificate for $DOMAIN will be issued automatically."
}

if [ -n "$DOMAIN" ]; then
  case "$PROXY_KIND" in
    caddy-host | install-caddy) setup_caddy ;;
    caddy-docker) setup_caddy_docker ;;
    nginx-host) setup_nginx ;;
    nginx-docker)
      log ""
      log "Dockerized nginx ($DOCKER_NGINX) detected. Certificate issuance inside"
      log "someone else's nginx container is too varied to automate safely, so add"
      log "this server block to that container's config and reload it:"
      log ""
      log "  server {"
      log "      listen 443 ssl;"
      log "      server_name $DOMAIN;"
      log "      # point ssl_certificate/ssl_certificate_key at a cert for this name"
      log "      location / {"
      log "          proxy_pass https://$GATEWAY:$AGENT_PORT;"
      log "          proxy_ssl_verify off;"
      log "          proxy_set_header Host \$host;"
      log "      }"
      log "  }"
      log ""
      log "Nginx Proxy Manager users: add a proxy host for $DOMAIN pointing at"
      log "$GATEWAY:$AGENT_PORT with HTTPS upstream and request a Let's Encrypt"
      log "certificate in its SSL tab."
      DOMAIN_MANUAL=1 ;;
  esac
  [ "${DOMAIN_MANUAL:-0}" = 1 ] || verify_domain || DOMAIN_UNVERIFIED=1
fi

log ""
log "=========================================="
log "aster-agent installed and running on $LISTEN"
if [ -n "$DOMAIN" ]; then
  if [ "${DOMAIN_UNVERIFIED:-0}" = 1 ]; then
    log "Domain mode configured but NOT yet reachable — see the warning above."
    log "Once it answers, add this machine in Aster.app with:"
  else
    log "Domain mode active and verified. In Aster.app add this machine with:"
  fi
  log "  https://$DOMAIN"
  log "No fingerprint comparison needed — the CA certificate is verified automatically."
elif [ -n "${FINGERPRINT:-}" ]; then
  log "TLS SHA-256 fingerprint (compare in Aster.app):"
  log "  $FINGERPRINT"
elif [ "$PLATFORM" = "darwin" ]; then
  log "fingerprint not captured yet; view it with:"
  log "  grep fingerprint $DARWIN_LOG"
else
  log "fingerprint not captured yet; view it with:"
  log "  journalctl -u $SERVICE | grep fingerprint"
fi
log "=========================================="
